     7→   1. CSS Custom Properties (Design Tokens)
     8→   ========================================================================== */
     9→
    10→:root {
    11→    /* Colors */
    12→    --color-primary: #000000;
    13→    --color-secondary: #ffffff;
    14→    --color-tint: #FF1493;
    15→    --color-accent: var(--color-tint);
    16→    --color-text: #333333;
    17→    --color-text-light: #666666;
    18→    --color-background: #ffffff;
    19→    --color-background-alt: #f8f8f8;
    20→    --color-border: #e0e0e0;
    21→
    22→    /* Typography */
    23→    --font-family: 'Georgia', 'Times New Roman', serif;
    24→    --font-family-headings: 'Georgia', 'Times New Roman', serif;
    25→    --font-size-small: 0.8125rem;   /* 13px */
    26→    --font-size-base: 1rem;          /* 16px */
    27→    --font-size-medium: 1.25rem;     /* 20px */
    28→    --font-size-large: 2.25rem;      /* 36px */
    29→    --font-size-xlarge: 2.625rem;    /* 42px */
    30→    --font-weight-normal: 400;
    31→    --font-weight-bold: 700;
    32→    --line-height-base: 1.6;
    33→    --line-height-heading: 1.2;
    34→
    35→    /* Spacing */
    36→    --spacing-unit: 1.5rem;          /* 24px */
    37→    --spacing-xs: calc(var(--spacing-unit) * 0.25);  /* 6px */
    38→    --spacing-sm: calc(var(--spacing-unit) * 0.5);   /* 12px */
    39→    --spacing-md: var(--spacing-unit);                /* 24px */
    40→    --spacing-lg: calc(var(--spacing-unit) * 2);     /* 48px */
    41→    --spacing-xl: calc(var(--spacing-unit) * 3);     /* 72px */
    42→    --spacing-section: calc(var(--spacing-unit) * 3); /* 72px */
    43→
    44→    /* Layout */
    45→    --container-max-width: 1200px;
    46→    --container-padding: var(--spacing-unit);
    47→
    48→    /* Transitions */
    49→    --transition-fast: 150ms ease-in-out;
    50→    --transition-base: 300ms ease-in-out;
    51→
    52→    /* Shadows */
    53→    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
    54→    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    55→    --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);
    56→
    57→    /* Border Radius */
    58→    --radius-sm: 0.25rem;
    59→    --radius-md: 0.5rem;
    60→    --radius-lg: 1rem;
    61→
    62→    /* Z-Index Scale */
    63→    --z-dropdown: 100;
    64→    --z-sticky: 200;
    65→    --z-fixed: 300;
    66→    --z-modal: 400;
    67→    --z-overlay: 500;
    68→}
    69→
    70→/* ==========================================================================
    71→   2. Base Reset
    72→   ========================================================================== */
    73→
    74→*,
    75→*::before,
    76→*::after {
    77→    box-sizing: border-box;
    78→}
    79→
    80→* {
    81→    margin: 0;
    82→    padding: 0;
    83→}
    84→
    85→html {
    86→    scroll-behavior: smooth;
    87→}
    88→
    89→body {
    90→    font-family: var(--font-family);
    91→    font-size: var(--font-size-base);
    92→    font-weight: var(--font-weight-normal);
    93→    line-height: var(--line-height-base);
    94→    color: var(--color-text);
    95→    background-color: var(--color-background);
    96→    -webkit-font-smoothing: antialiased;
    97→    -moz-osx-font-smoothing: grayscale;
    98→}
    99→
   100→img,
   101→picture,
   102→video,
   103→canvas,
   104→svg {
   105→    display: block;
   106→    max-width: 100%;
   107→    height: auto;
   108→}
   109→
   110→input,
   111→button,
   112→textarea,
   113→select {
   114→    font: inherit;
   115→}
