   120→
   121→h1, h2, h3, h4, h5, h6 {
   122→    font-family: var(--font-family-headings);
   123→    font-weight: var(--font-weight-bold);
   124→    line-height: var(--line-height-heading);
   125→    color: var(--color-primary);
   126→    margin-bottom: var(--spacing-md);
   127→}
   128→
   129→h1 {
   130→    font-size: var(--font-size-xlarge);
   131→}
   132→
   133→h2 {
   134→    font-size: var(--font-size-large);
   135→}
   136→
   137→h3 {
   138→    font-size: var(--font-size-medium);
   139→}
   140→
   141→h4, h5, h6 {
   142→    font-size: var(--font-size-base);
   143→}
   144→
   145→p {
   146→    margin-bottom: var(--spacing-md);
   147→}
   148→
   149→p:last-child {
   150→    margin-bottom: 0;
   151→}
   152→
   153→a {
   154→    color: var(--color-primary);
   155→    text-decoration: underline;
   156→    transition: color var(--transition-fast);
   157→}
   158→
   159→a:hover,
   160→a:focus {
   161→    color: var(--color-accent);
   162→}
   163→
   164→ul, ol {
   165→    margin-bottom: var(--spacing-md);
   166→    padding-left: var(--spacing-md);
   167→}
   168→
   169→li {
   170→    margin-bottom: var(--spacing-xs);
   171→}
   172→
   173→li:last-child {
   174→    margin-bottom: 0;
   175→}
   176→
   177→strong, b {
   178→    font-weight: var(--font-weight-bold);
   179→}
   180→
   181→small {
   182→    font-size: var(--font-size-small);
   183→}
   184→
   185→/* ==========================================================================
   186→   4. Layout - Container
   187→   ========================================================================== */
   188→
   189→.container {
   190→    width: 100%;
   191→    max-width: var(--container-max-width);
   192→    margin-left: auto;
   193→    margin-right: auto;
   194→    padding-left: var(--container-padding);
   195→    padding-right: var(--container-padding);
   196→}
   197→
   198→.container-narrow {
   199→    max-width: 800px;
   200→}
   201→
   202→.container-wide {
   203→    max-width: 1400px;
   204→}
   205→
   206→/* Main content area */
   207→main {
   208→    min-height: 100vh;
   209→}
   210→
   211→/* Section spacing */
   212→.section {
   213→    padding-top: var(--spacing-section);
   214→    padding-bottom: var(--spacing-section);
   215→}
   216→
   217→.section-alt {
   218→    background-color: var(--color-background-alt);
   219→}
   220→
   221→/* Visually hidden but accessible */
   222→.sr-only {
   223→    position: absolute;
   224→    width: 1px;
   225→    height: 1px;
   226→    padding: 0;
   227→    margin: -1px;
   228→    overflow: hidden;
   229→    clip: rect(0, 0, 0, 0);
   230→    white-space: nowrap;
   231→    border: 0;
   232→}
   233→
   234→/* ==========================================================================
   235→   5. Navigation
   236→   ========================================================================== */
   237→
   238→.site-header {
   239→    position: sticky;
   240→    top: 0;
   241→    z-index: var(--z-sticky);
   242→    background-color: var(--color-background);
   243→    border-bottom: 1px solid var(--color-border);
   244→}
   245→
   246→.main-nav {
   247→    padding: var(--spacing-sm) 0;
   248→}
   249→
   250→.nav-container {
   251→    display: flex;
   252→    align-items: center;
   253→    justify-content: space-between;
   254→    max-width: var(--container-max-width);
   255→    margin: 0 auto;
   256→    padding: 0 var(--container-padding);
   257→}
   258→
   259→/* Logo / Site Title */
   260→.nav-logo {
   261→    text-decoration: none;
   262→    color: var(--color-primary);
   263→    transition: color var(--transition-fast);
   264→}
   265→
   266→.nav-logo:hover,
   267→.nav-logo:focus {
   268→    color: var(--color-accent);
   269→}
   270→
   271→.nav-title {
   272→    font-family: var(--font-family-headings);
   273→    font-size: var(--font-size-medium);
   274→    font-weight: var(--font-weight-bold);
   275→}
   276→
   277→/* Navigation Menu */
   278→.nav-menu {
   279→    display: flex;
   280→    align-items: center;
   281→    gap: var(--spacing-md);
   282→    list-style: none;
   283→    margin: 0;
   284→    padding: 0;
   285→}
   286→
   287→.nav-menu li {
   288→    margin: 0;
